def feature(s):
    if not s:
        return 0.0
    v = s.get('volume_per_atom_A3')
    if v is None or v <= 0:
        return 0.0
    p = s.get('element_properties') or {}
    c = s.get('composition') or {}
    total = 0.0
    weight = 0.0
    for e, x in c.items():
        r = (p.get(e) or {}).get('covalent_radius_A')
        if x is not None and x > 0 and r is not None and r > 0:
            total += x * r ** 3
            weight += x
    if weight <= 0:
        return 0.0
    return 4.0 * pi * total / (3.0 * weight * v)

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    if n == 0:
        return 0.0
    p = s.get('element_properties') or {}
    radii = [(p.get(a.get('element')) or {}).get('covalent_radius_A') for a in sites]
    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    shortest = [inf] * n
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and occ[i] > 0 and occ[j] > 0:
            ri = radii[i]
            rj = radii[j]
            if ri is not None and rj is not None and ri > 0 and rj > 0:
                shortest[i] = min(shortest[i], d / (ri + rj))
    total = 0.0
    weight = 0.0
    for i in range(n):
        if isfinite(shortest[i]) and occ[i] > 0:
            total += occ[i] * shortest[i]
            weight += occ[i]
    return total / weight if weight > 0 else 0.0

