def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    nearest = [inf] * n
    edges = s.get('neighbors') or []
    for b in edges:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and occ[j] > 0:
            nearest[i] = min(nearest[i], d)
    coord = [0.0] * n
    for b in edges:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and isfinite(nearest[i]) and d <= 1.6 * nearest[i]:
            coord[i] += occ[j] * exp(1.0 - (d / nearest[i]) ** 6)
    w = sum(occ)
    if w <= 0:
        return 0.0
    mean = sum(occ[i] * coord[i] for i in range(n)) / w
    return sqrt(max(sum(occ[i] * (coord[i] - mean) ** 2 for i in range(n)) / w, 0.0))

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    p = s.get('element_properties') or {}
    radii = [(p.get(a.get('element')) or {}).get('covalent_radius_A') for a in sites]
    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    weight = sum(occ)
    if weight <= 0:
        return 0.0
    total = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8:
            ri = radii[i]
            rj = radii[j]
            if ri is not None and rj is not None and ri > 0 and rj > 0:
                overlap = min(max((ri + rj) / d - 1.0, 0.0), 3.0)
                total += occ[i] * occ[j] * overlap * overlap
    return total / (2.0 * weight)

def feature(s):
    if not s:
        return 0.0
    v = s.get('volume_per_atom_A3')
    if v is None or v <= 0:
        return 0.0
    p = s.get('element_properties') or {}
    total = 0.0
    weight = 0.0
    for e, x in (s.get('composition') or {}).items():
        z = (p.get(e) or {}).get('valence_electrons')
        if x is not None and x > 0 and z is not None and z >= 0:
            total += x * z
            weight += x
    return total / (weight * v) if weight > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    matrix = (s.get('lattice') or {}).get('matrix')
    if matrix is None or len(matrix) != 3:
        return 0.0
    a = np.asarray(matrix, dtype=float)
    if a.shape != (3, 3) or not np.all(np.isfinite(a)):
        return 0.0
    eigenvalues = np.linalg.eigvalsh(np.matmul(a, a.T))
    lo = float(eigenvalues[0])
    hi = float(eigenvalues[2])
    if lo <= 1e-12 or hi <= 0:
        return 0.0
    return 0.5 * log(hi / lo)

def feature(s):
    if not s:
        return 0.0
    p = s.get('element_properties') or {}
    total = 0.0
    weight = 0.0
    for e, x in (s.get('composition') or {}).items():
        a = p.get(e) or {}
        ie = a.get('first_ionization_energy_eV')
        ea = a.get('electron_affinity_eV')
        if x is not None and x > 0 and ie is not None and ea is not None:
            total += x * (ie - ea)
            weight += x
    return total / weight if weight > 0 else 0.0
